// Issue 40382: Client calls Close multiple times on Request.Body.
func TestClientCallsCloseOnlyOnce(t *testing.T) {
	// Flaky on HTTP/3.
	run(t, testClientCallsCloseOnlyOnce, http3SkippedMode)
